import { BottomSheetModalProvider } from "@gorhom/bottom-sheet";
import { ImageZoom } from "@likashefqet/react-native-image-zoom";
import { animateParallel, Block, Text } from "@prototyp/skeletor";
import { ProfileDetails_Tags } from "@unomed/react-native-matrix-sdk";
import { format } from "date-fns";
import { useAtom, useSetAtom } from "jotai";
import { TimelineAtoms } from "modules/timeline/jotai";
import type { FC } from "react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  Dimensions,
  Image,
  Modal,
  StyleSheet,
  TouchableOpacity,
} from "react-native";
import { ImageInfoBottomSheet } from "screens/room/fragments/image-info-bottom-sheet";
import { Colors, TextSize } from "shared/styles";
import {
  cacheImage,
  getCachedImagePathByURL,
} from "shared/utils/image-caching";
import { BlurGradientOverlay } from "../blur-gradient-overlay";
import { Button } from "../button";
import { Loading } from "../loading";

const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = Dimensions.get("window");

const isLocalUri = (uri: string) => uri.startsWith("file://");

export const ImageViewerModal: FC = () => {
  const [payload, setPayload] = useAtom(TimelineAtoms.imageViewerPayload);
  const [localUri, setLocalUri] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [hasError, setHasError] = useState(false);
  const [showControls, setShowControls] = useState(true);
  const uri = payload?.uri ?? null;
  const event = payload?.event ?? null;
  const roomId = payload?.roomId ?? null;
  const visible = !!uri;
  const hasEventContext = !!event && !!roomId;
  const setImageInfoPayload = useSetAtom(TimelineAtoms.imageInfoPayload);

  const senderName = useMemo(() => {
    if (!event) return null;
    if (event.senderProfile.tag === ProfileDetails_Tags.Ready) {
      return event.senderProfile.inner.displayName ?? event.sender;
    }
    return event.sender;
  }, [event]);

  const formattedDate = useMemo(() => {
    if (!event) return null;
    return format(Number(event.timestamp), "MMM d, HH:mm");
  }, [event]);

  const controlsAnimation = useRef(
    animateParallel(
      { translateY: [-120, 0], opacity: [0, 1] },
      { duration: 280 },
    ),
  ).current;

  useEffect(() => {
    if (showControls) controlsAnimation.start();
    else controlsAnimation.reverse();
  }, [showControls]);

  useEffect(() => {
    if (!uri) return;

    let cancelled = false;
    setLocalUri(null);
    setIsLoading(true);
    setHasError(false);

    const load = async () => {
      try {
        if (isLocalUri(uri)) {
          setLocalUri(uri);
          return;
        }

        await cacheImage(uri);
        if (cancelled) return;
        setLocalUri(getCachedImagePathByURL(uri));
      } catch {
        if (cancelled) return;
        setIsLoading(false);
        setHasError(true);
      }
    };

    load();

    return () => {
      cancelled = true;
    };
  }, [uri]);

  const onClose = useCallback(() => {
    setPayload(null);
    setLocalUri(null);
    setHasError(false);
    setIsLoading(true);
    setShowControls(true);
  }, [setPayload]);

  const handleSingleTap = useCallback(() => {
    setShowControls((prev) => !prev);
  }, []);

  const handleImageLoad = useCallback(() => {
    setIsLoading(false);
    setHasError(false);
  }, []);

  const handleImageError = useCallback(() => {
    setIsLoading(false);
    setHasError(true);
  }, []);

  const handleRetry = useCallback(async () => {
    if (!uri) return;
    setLocalUri(null);
    setIsLoading(true);
    setHasError(false);

    try {
      if (isLocalUri(uri)) {
        setLocalUri(uri);
        return;
      }

      await cacheImage(uri);
      setLocalUri(getCachedImagePathByURL(uri));
    } catch {
      setIsLoading(false);
      setHasError(true);
    }
  }, [uri]);

  const handleOpenInfo = useCallback(() => {
    if (!event || !roomId) return;
    setImageInfoPayload({ event, roomId, localUri });
  }, [event, roomId, localUri, setImageInfoPayload]);

  if (!visible) return null;

  return (
    <Modal
      visible={visible}
      animationType="fade"
      statusBarTranslucent
      transparent
      onRequestClose={onClose}
    >
      <BottomSheetModalProvider>
        <Block
          background={Colors.black}
          flex={1}
          justify="center"
          align="center"
        >
          <Block
            absolute
            offsets={{ top: 0, left: 0, right: 0 }}
            zIndex={10}
            paddings={[56, 20, 16, 20]}
            flexDirection="row"
            align="center"
            justify="space-between"
            gap={12}
            background={Colors.primary}
            animations={controlsAnimation.animations}
            pointerEvents={showControls ? "auto" : "none"}
          >
            <BlurGradientOverlay />
            <Block width={60} align="flex-start" zIndex={2}>
              {hasEventContext && (
                <Button.Wrapper onPress={handleOpenInfo}>
                  <Image
                    source={require("assets/icons/info.png")}
                    style={styles.infoIcon}
                    tintColor={Colors.white}
                  />
                </Button.Wrapper>
              )}
            </Block>
            <Block flex={1} align="center" gap={2} zIndex={2}>
              {senderName && (
                <Text
                  color={Colors.white}
                  font="InstrumentSans-Semibold"
                  numberOfLines={1}
                >
                  {senderName}
                </Text>
              )}
              {formattedDate && (
                <Text
                  size={TextSize.tiny}
                  color={Colors.white80}
                  numberOfLines={1}
                >
                  {formattedDate}
                </Text>
              )}
            </Block>
            <Block width={60} align="flex-end" zIndex={2}>
              <Button.Wrapper onPress={onClose}>
                <Text font="InstrumentSans-Semibold" color={Colors.white}>
                  Close
                </Text>
              </Button.Wrapper>
            </Block>
          </Block>

          <Block width={SCREEN_WIDTH} height={SCREEN_HEIGHT}>
            {isLoading && !hasError && (
              <Block
                absolute
                width={SCREEN_WIDTH}
                height={SCREEN_HEIGHT}
                align="center"
                justify="center"
                zIndex={5}
                background={Colors.white10}
              >
                <Loading isFullScreen={false} />
              </Block>
            )}

            {hasError ? (
              <Block
                width={SCREEN_WIDTH}
                height={SCREEN_HEIGHT}
                align="center"
                justify="center"
              >
                <Text color={Colors.white}>Failed to load image</Text>
                <TouchableOpacity
                  onPress={handleRetry}
                  style={styles.retryButton}
                >
                  <Text size={TextSize.small} color={Colors.white}>
                    Tap to retry
                  </Text>
                </TouchableOpacity>
              </Block>
            ) : localUri ? (
              <ImageZoom
                key={localUri}
                uri={localUri}
                minScale={1}
                maxScale={5}
                maxPanPointers={2}
                isPanEnabled
                isPinchEnabled
                isDoubleTapEnabled
                isSingleTapEnabled
                style={styles.image}
                onLoad={handleImageLoad}
                onError={handleImageError}
                onSingleTap={handleSingleTap}
              />
            ) : null}
          </Block>
        </Block>
        <ImageInfoBottomSheet />
      </BottomSheetModalProvider>
    </Modal>
  );
};

const styles = StyleSheet.create({
  image: {
    width: SCREEN_WIDTH,
    height: SCREEN_HEIGHT,
  },
  retryButton: {
    marginTop: 12,
    paddingVertical: 8,
    paddingHorizontal: 16,
  },
  infoIcon: {
    width: 24,
    height: 24,
  },
});

import type {
  EventTimelineItem,
  RoomInterface,
  TaskHandleInterface,
  TimelineInterface,
} from "@unomed/react-native-matrix-sdk";
import {
  DateDividerMode,
  RoomMessageEventMessageType,
  TimelineDiff_Tags,
  TimelineFilter,
  TimelineFocus,
  TimelineReadReceiptTracking,
} from "@unomed/react-native-matrix-sdk";
import { getEventId } from "modules/matrix-client/utils";
import { useCallback, useEffect, useRef, useState } from "react";

//TODO: Make a timeline module

interface UseMediaTimelineProps {
  room: RoomInterface | undefined;
  roomId: string;
}

export const useMediaTimeline = ({ room, roomId }: UseMediaTimelineProps) => {
  const [mediaItems, setMediaItems] = useState<EventTimelineItem[]>([]);
  const [loading, setLoading] = useState(true);
  const eventIdsRef = useRef<Set<string>>(new Set());
  const timelineRef = useRef<TimelineInterface | null>(null);

  const upsertMediaItems = useCallback((incoming: EventTimelineItem[]) => {
    setMediaItems((prev) => {
      const next = [...prev];
      for (const event of incoming) {
        const id = getEventId(event);
        if (!id || eventIdsRef.current.has(id)) continue;

        eventIdsRef.current.add(id);
        next.push(event);
      }
      return next.sort((a, b) => Number(b.timestamp) - Number(a.timestamp));
    });
  }, []);

  useEffect(() => {
    if (!room) return;

    setLoading(true);
    setMediaItems([]);
    eventIdsRef.current.clear();

    let timelineListenerHandle: TaskHandleInterface | null = null;

    const initMediaTimeline = async () => {
      try {
        const timeline = await room.timelineWithConfiguration({
          focus: new TimelineFocus.Live({ hideThreadedEvents: false }),
          filter: new TimelineFilter.OnlyMessage({
            types: [
              RoomMessageEventMessageType.Image,
              RoomMessageEventMessageType.Video,
              RoomMessageEventMessageType.File,
              RoomMessageEventMessageType.Audio,
            ],
          }),
          internalIdPrefix: "media_",
          dateDividerMode: DateDividerMode.Daily,
          trackReadReceipts: TimelineReadReceiptTracking.Disabled,
          reportUtds: false,
        });

        timelineRef.current = timeline;

        // Set up timeline listener for updates
        timelineListenerHandle = await timeline.addListener({
          onUpdate: (diffs) => {
            diffs.forEach((diff) => {
              const change = diff.tag;
              switch (change) {
                case TimelineDiff_Tags.Append: {
                  const newItems = diff.inner.values;
                  if (newItems.length) {
                    const eventItems = newItems
                      .map((i) => i.asEvent())
                      .filter((i): i is EventTimelineItem => !!i);
                    if (eventItems.length > 0) upsertMediaItems(eventItems);
                  }
                  break;
                }
                case TimelineDiff_Tags.Insert:
                case TimelineDiff_Tags.PushFront:
                case TimelineDiff_Tags.PushBack: {
                  const { value } = diff.inner;
                  const ev = value.asEvent();
                  if (ev) upsertMediaItems([ev]);
                  break;
                }
                case TimelineDiff_Tags.Set: {
                  const { value } = diff.inner;
                  const ev = value.asEvent();
                  if (ev) {
                    const id = getEventId(ev);
                    if (!id) break;

                    setMediaItems((prev) => {
                      const existingIndex = prev.findIndex(
                        (item) => getEventId(item) === id,
                      );
                      if (existingIndex >= 0) {
                        const next = [...prev];
                        next[existingIndex] = ev;
                        return next;
                      }
                      return prev;
                    });
                  }
                  break;
                }
                case TimelineDiff_Tags.Remove: {
                  const { index: removeIndex } = diff.inner;
                  setMediaItems((prev) => {
                    const next = prev.filter((_, idx) => idx !== removeIndex);
                    eventIdsRef.current = new Set(
                      next
                        .map((item) => getEventId(item))
                        .filter(Boolean) as string[],
                    );
                    return next;
                  });
                  break;
                }
                case TimelineDiff_Tags.Reset: {
                  const resetItems = diff.inner.values;
                  if (resetItems.length) {
                    const eventItems = resetItems
                      .map((i) => i.asEvent())
                      .filter((i): i is EventTimelineItem => !!i);

                    const seenIds = new Set<string>();
                    const newMediaItems: EventTimelineItem[] = [];

                    for (const event of eventItems) {
                      const id = getEventId(event);
                      if (id && !seenIds.has(id)) {
                        seenIds.add(id);
                        newMediaItems.push(event);
                      }
                    }

                    eventIdsRef.current = seenIds;
                    setMediaItems(
                      newMediaItems.sort(
                        (a, b) => Number(b.timestamp) - Number(a.timestamp),
                      ),
                    );
                  }
                  break;
                }
                case TimelineDiff_Tags.Clear: {
                  eventIdsRef.current.clear();
                  setMediaItems([]);
                  break;
                }
                default:
                  break;
              }
            });
          },
        });

        // Paginate backwards until we reach the start of the timeline
        let reachedStart = false;
        while (!reachedStart) {
          reachedStart = await timeline.paginateBackwards(100);
        }

        setLoading(false);
      } catch (error) {
        console.error("Failed to initialize media timeline:", error);
        setLoading(false);
      }
    };

    initMediaTimeline();

    return () => {
      timelineListenerHandle?.cancel?.();
      timelineRef.current = null;
    };
  }, [roomId, room, upsertMediaItems]);

  return {
    mediaItems,
    loading,
  };
};

import { Block, Text } from "@prototyp/skeletor";
import {
  type EventTimelineItem,
  type ImageMessageContent,
  MessageType_Tags,
  MsgLikeKind_Tags,
  type RoomInterface,
  TimelineItemContent_Tags,
  type VideoMessageContent,
} from "@unomed/react-native-matrix-sdk";
import { useSetAtom } from "jotai";
import { TimelineAtoms } from "modules/timeline/jotai";
import { type FC, useMemo, useState } from "react";
import { StyleSheet } from "react-native";
import { useMediaTimeline } from "screens/room-media/hooks";
import { Button } from "shared/components";
import { Colors, TextSize } from "shared/styles";
import { FilesList } from "../files-list";
import { MediaList } from "../media-list";

interface Props {
  room: RoomInterface;
}

type Tab = "media" | "files";

function isMediaItem(event: EventTimelineItem): boolean {
  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
    const kind = event.content.inner.content.kind;
    if (kind?.tag === MsgLikeKind_Tags.Message) {
      const tag = kind.inner.content.msgType?.tag;
      return tag === MessageType_Tags.Image || tag === MessageType_Tags.Video;
    }
  }
  return false;
}

function isFileItem(event: EventTimelineItem): boolean {
  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
    const kind = event.content.inner.content.kind;
    if (kind?.tag === MsgLikeKind_Tags.Message) {
      const tag = kind.inner.content.msgType?.tag;
      return tag === MessageType_Tags.File || tag === MessageType_Tags.Audio;
    }
  }
  return false;
}

export const MediaGallery: FC<Props> = ({ room }) => {
  const { mediaItems: allItems, loading } = useMediaTimeline({
    room,
    roomId: room.id(),
  });
  const [activeTab, setActiveTab] = useState<Tab>("media");
  const mediaItems = useMemo(() => allItems.filter(isMediaItem), [allItems]);
  const fileItems = useMemo(() => allItems.filter(isFileItem), [allItems]);
  const isMediaEmpty = !mediaItems.length;
  const isFileEmpty = !fileItems.length;
  const setImageViewerPayload = useSetAtom(TimelineAtoms.imageViewerPayload);
  const setVideoViewerPayload = useSetAtom(TimelineAtoms.videoViewerPayload);

  const handleSetActiveImageUri = (
    uri: string | null,
    type?: "image" | "video",
    content?: ImageMessageContent | VideoMessageContent,
    event?: EventTimelineItem,
  ) => {
    if (!type) return;
    const roomId = room.id();
    if (type === "image" && uri) {
      setImageViewerPayload({ uri, event, roomId });
      return;
    }
    if (type === "video" && content) {
      setVideoViewerPayload({
        content: content as VideoMessageContent,
        event,
        roomId,
      });
    }
  };

  return (
    <Block flex={1}>
      <Block flexDirection="row" margins={{ marginBottom: 16 }}>
        {(["media", "files"] as Tab[]).map((tab) => (
          <Button.Wrapper
            key={tab}
            onPress={() => setActiveTab(tab)}
            style={styles.tab}
          >
            <Block
              align="center"
              paddings={[10, 0]}
              border={{
                borderBottomWidth: 2,
                borderBottomColor:
                  activeTab === tab ? Colors.primary : Colors.white20,
              }}
            >
              <Text
                size={TextSize.small}
                color={activeTab === tab ? Colors.white : Colors.white50}
                textTransform="capitalize"
              >
                {tab}
              </Text>
            </Block>
          </Button.Wrapper>
        ))}
      </Block>

      {activeTab === "media" ? (
        <Block flex={1}>
          <MediaList
            items={mediaItems}
            loading={loading}
            isEmpty={isMediaEmpty}
            onPressItem={handleSetActiveImageUri}
          />
        </Block>
      ) : (
        <FilesList items={fileItems} loading={loading} isEmpty={isFileEmpty} />
      )}
    </Block>
  );
};

const styles = StyleSheet.create({
  tab: {
    flex: 1,
  },
});

import type {
  EventTimelineItem,
  RoomInterface,
  TaskHandleInterface,
  TimelineInterface,
  TimelineItemInterface,
} from "@unomed/react-native-matrix-sdk";
import {
  DateDividerMode,
  ReceiptType,
  TimelineDiff_Tags,
  TimelineFilter,
  TimelineFocus,
  TimelineReadReceiptTracking,
} from "@unomed/react-native-matrix-sdk";
import {
  getItemUniqueKey,
  getTransactionId,
} from "modules/matrix-client/utils";
import { NavigationContainerRef } from "modules/navigation/const";
import { useCallback, useEffect, useRef, useState } from "react";
import { AppState } from "react-native";
import { offlineToastHelper } from "shared/utils";

interface Props {
  room: RoomInterface | undefined;
  roomId: string;
}

const TIMELINE_PAGE_SIZE = 20;
const MIN_INITIAL_EVENTS = 10;
const ENABLE_TIMELINE_DEBUG = __DEV__;

export const useRoomTimeline = ({ room, roomId }: Props) => {
  const [events, setEvents] = useState<EventTimelineItem[]>([]);
  const eventIdsRef = useRef<Set<string>>(new Set());
  const timelineItemsRef = useRef<Array<EventTimelineItem | null>>([]);
  const timelineRef = useRef<TimelineInterface | null>(null);
  const isPaginatingRef = useRef(false);
  const reachedStartRef = useRef(false);
  // const setPinnedEventIds = useSetAtom(TimelineAtoms.pinnedEventIds);
  const [isDirect, setIsDirect] = useState(false);
  /** FIFO queue of transactionIds for in-flight own messages, used to match the final echo Set diff */
  const pendingTransactionIdsQueue = useRef<string[]>([]);
  const rebuildTimerRef = useRef<ReturnType<typeof setTimeout>>(undefined);
  const toEventItem = (item: TimelineItemInterface): EventTimelineItem | null =>
    item.asEvent() ?? null;

  const rebuildEventsFromTimelineItems = useCallback(() => {
    const seenIds = new Set<string>();
    const nextEvents: EventTimelineItem[] = [];

    for (const item of timelineItemsRef.current) {
      if (!item) continue;
      const key = getItemUniqueKey(item);
      if (key) {
        if (seenIds.has(key)) continue;
        seenIds.add(key);
      }
      nextEvents.push(item);
    }

    eventIdsRef.current = seenIds;
    setEvents(nextEvents);
  }, []);

  const markAsRead = useCallback(async () => {
    if (!room) return;
    if (AppState.currentState !== "active") return;

    try {
      await room.markAsRead(ReceiptType.Read);
    } catch (error) {
      console.error("Failed to mark room as read:", error);
    }
  }, [room]);

  const loadMoreMessages = useCallback(async () => {
    if (
      !timelineRef.current ||
      isPaginatingRef.current ||
      reachedStartRef.current
    ) {
      return;
    }

    isPaginatingRef.current = true;

    try {
      const hitStart =
        await timelineRef.current.paginateBackwards(TIMELINE_PAGE_SIZE);
      if (!hitStart) return;
      reachedStartRef.current = true;
    } catch (error) {
      console.error("Failed to load more messages:", error);
    } finally {
      isPaginatingRef.current = false;
    }
  }, []);

  //Hide for now pinned events, because it's not working as expected
  // useEffect(() => {
  //   if (!room) return;
  //   setPinnedEventIds([]);
  //   room
  //     .roomInfo()
  //     .then((info) => {
  //       console.log(info);
  //       setPinnedEventIds(info.pinnedEventIds || []);
  //     })
  //     .catch(console.error);
  //   const handle = room.subscribeToRoomInfoUpdates({
  //     call: (info) => {
  //       console.log(info);
  //       setPinnedEventIds(info.pinnedEventIds || []);
  //     },
  //   });
  //   return () => handle.cancel();
  // }, [room, setPinnedEventIds]);

  useEffect(() => {
    if (!room) return;

    // Reset state when room changes
    setEvents([]);
    timelineItemsRef.current = [];
    eventIdsRef.current.clear();
    pendingTransactionIdsQueue.current = [];

    let timelineListenerHandle: TaskHandleInterface | null = null;
    let isDisposed = false;

    const initRoomTimeline = async () => {
      try {
        const timeline = await room.timelineWithConfiguration({
          focus: new TimelineFocus.Live({ hideThreadedEvents: false }),
          filter: new TimelineFilter.All(),
          internalIdPrefix: undefined,
          dateDividerMode: DateDividerMode.Daily,
          trackReadReceipts: TimelineReadReceiptTracking.AllEvents,
          reportUtds: false,
        });

        // Store timeline in ref for reuse in pagination
        timelineRef.current = timeline;

        // Set up listener BEFORE paginateBackwards so the SDK's initial
        // cached diffs (from SQLite) are received immediately — no network needed.
        // Set up timeline listener for real-time updates
        timelineListenerHandle = await timeline.addListener({
          onUpdate: (diffs) => {
            const beforeCount = timelineItemsRef.current.length;
            diffs.forEach((diff) => {
              const change = diff.tag;
              const timelineItems = timelineItemsRef.current;
              switch (change) {
                case TimelineDiff_Tags.Append: {
                  if (diff.inner.values.length > 0) {
                    timelineItems.push(...diff.inner.values.map(toEventItem));
                  }
                  break;
                }
                case TimelineDiff_Tags.Insert: {
                  const { index, value } = diff.inner;
                  timelineItems.splice(index, 0, toEventItem(value));
                  break;
                }
                case TimelineDiff_Tags.Set: {
                  const { index, value } = diff.inner;
                  const ev = toEventItem(value);
                  timelineItems[index] = ev;

                  // transactionId -> eventId transition can arrive in an order where
                  // a stale local echo still exists elsewhere in the list.
                  if (
                    ev?.isOwn &&
                    !ev.localSendState &&
                    pendingTransactionIdsQueue.current.length > 0
                  ) {
                    const txId = pendingTransactionIdsQueue.current.shift();
                    if (txId) {
                      const txIndex = timelineItems.findIndex((item) => {
                        if (!item) return false;
                        return getItemUniqueKey(item) === txId;
                      });
                      if (txIndex !== -1) {
                        timelineItems[txIndex] = ev;
                      }
                    }
                  }
                  break;
                }
                case TimelineDiff_Tags.Remove: {
                  const { index: removeIndex } = diff.inner;
                  if (removeIndex >= 0 && removeIndex < timelineItems.length) {
                    timelineItems.splice(removeIndex, 1);
                  }
                  break;
                }
                case TimelineDiff_Tags.PushFront: {
                  const { value } = diff.inner;
                  timelineItems.unshift(toEventItem(value));
                  break;
                }
                case TimelineDiff_Tags.PushBack: {
                  const { value } = diff.inner;
                  const ev = toEventItem(value);
                  timelineItems.push(ev);
                  if (ev) {
                    const txId = getTransactionId(ev);
                    if (txId) {
                      pendingTransactionIdsQueue.current.push(txId);
                    }
                  }
                  break;
                }
                case TimelineDiff_Tags.PopFront: {
                  timelineItems.shift();
                  break;
                }
                case TimelineDiff_Tags.PopBack: {
                  timelineItems.pop();
                  break;
                }
                case TimelineDiff_Tags.Reset: {
                  const resetItems = diff.inner.values;
                  pendingTransactionIdsQueue.current = [];
                  timelineItemsRef.current = resetItems.map(toEventItem);

                  const eventItems = timelineItemsRef.current.filter(
                    (i): i is EventTimelineItem => !!i,
                  );
                  pendingTransactionIdsQueue.current = eventItems
                    .map(getTransactionId)
                    .filter((id): id is string => !!id);
                  break;
                }
                case TimelineDiff_Tags.Truncate: {
                  const { length: cut } = diff.inner;
                  timelineItems.length = cut;
                  break;
                }
                case TimelineDiff_Tags.Clear: {
                  timelineItemsRef.current = [];
                  pendingTransactionIdsQueue.current = [];
                  eventIdsRef.current = new Set();
                  setEvents([]);
                  break;
                }
                default:
                  console.log("Unknown timeline change type:", change);
              }
            });

            if (diffs.some((diff) => diff.tag !== TimelineDiff_Tags.Clear)) {
              if (rebuildTimerRef.current) {
                clearTimeout(rebuildTimerRef.current);
              }
              rebuildTimerRef.current = setTimeout(
                rebuildEventsFromTimelineItems,
                0,
              );
            }

            if (ENABLE_TIMELINE_DEBUG) {
              const afterCount = timelineItemsRef.current.length;
              const tags = diffs.map((d) => d.tag).join(", ");
              console.log(
                `[TimelineDebug][${roomId}] diffs=[${tags}] items ${beforeCount}->${afterCount}`,
              );
            }
          },
        });

        // Paginate after the listener is set up so events flow through it.
        // Loop until we have at least MIN_INITIAL_EVENTS or reach the start.
        isPaginatingRef.current = true;
        (async () => {
          try {
            let hitStart = false;
            while (!isDisposed && !hitStart) {
              hitStart = await timeline.paginateBackwards(TIMELINE_PAGE_SIZE);
              if (hitStart) {
                reachedStartRef.current = true;
                break;
              }
              const eventCount =
                timelineItemsRef.current.filter(Boolean).length;
              if (eventCount >= MIN_INITIAL_EVENTS) break;
            }
          } catch (error) {
            if (!isDisposed) {
              console.warn("Failed to load initial messages:", error);
            }
          } finally {
            isPaginatingRef.current = false;
          }
        })();
      } catch (error) {
        console.error("Failed to initialize room timeline:", error);
        offlineToastHelper("Failed to load the messages. Please try again.");
        NavigationContainerRef.goBack();
        return null;
      }
    };

    initRoomTimeline();

    return () => {
      isDisposed = true;
      timelineListenerHandle?.cancel?.();
      if (rebuildTimerRef.current) clearTimeout(rebuildTimerRef.current);
      timelineRef.current = null;
      timelineItemsRef.current = [];
      isPaginatingRef.current = false;
      reachedStartRef.current = false;
    };
  }, [rebuildEventsFromTimelineItems, room, roomId]);

  useEffect(() => {
    markAsRead().catch(console.error);
    room?.isDirect().then(setIsDirect).catch(console.error);
  }, [room, markAsRead]);

  return {
    events,
    timelineRef,
    isPaginatingRef,
    reachedStartRef,
    isDirect,
    loadMoreMessages,
    markAsRead,
  };
};

import { FlashList, type FlashListRef } from "@shopify/flash-list";
import type { RoomInterface } from "@unomed/react-native-matrix-sdk";
import { TimelineItemContent_Tags } from "@unomed/react-native-matrix-sdk";
import { useAtom } from "jotai";
import {
  addDateDividers,
  getEventId,
  getItemUniqueKey,
  groupInfoEvents,
} from "modules/matrix-client/utils";
import { useRoomIdentityViolations } from "modules/room/hooks";
import { useRoomTimeline } from "modules/timeline/hooks";
import { TimelineAtoms } from "modules/timeline/jotai";
import { filterSameStateKey } from "modules/timeline/utils";
import {
  type FC,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import {
  KeyboardAvoidingView,
  type NativeScrollEvent,
  type NativeSyntheticEvent,
  StyleSheet,
} from "react-native";
import { MemberDetailsBottomSheet, SeenByBottomSheet } from "shared/components";
import { useMemberDetails } from "shared/hooks";
import { DateDivider } from "../date-divider";
import { FailedEchoBottomSheet } from "../failed-echo-bottom-sheet";
import { GroupedInfoMessages } from "../grouped-info-messages";
import { MessageContentBottomSheet } from "../message-content-bottom-sheet";
import { NewMessagesButton } from "../new-messages-button";
import { ReactionsBottomSheet } from "../reactions-bottom-sheet";
import { RoomIdentityBanner } from "../room-identity-banner";
import { RoomInput } from "../room-input";
import { ScrollToBottomButton } from "../scroll-to-bottom-button";
import { ShieldModal } from "../shield-modal";
import { SingleMessageType } from "../single-message-type";

interface Props {
  room: RoomInterface;
  roomId: string;
}

export const RoomTimeline: FC<Props> = ({ room, roomId }) => {
  const flashListRef = useRef<FlashListRef<TimelineListItem>>(null);
  const isAtBottomRef = useRef(true);
  const suppressScrollDownRef = useRef(false);
  const lastEventKeyRef = useRef<string | undefined>(undefined);
  const visibleHeightRef = useRef(0);
  const [showNewMessageArrived, setShowNewMessageArrived] = useState(false);
  const [showScrollDown, setShowScrollDown] = useState(false);
  const {
    events,
    isPaginatingRef,
    reachedStartRef,
    isDirect,
    loadMoreMessages,
    markAsRead,
  } = useRoomTimeline({
    room,
    roomId,
  });
  const [scrollToEventId, setScrollToEventId] = useAtom(
    TimelineAtoms.scrollToEventId,
  );
  const [seenByUsers, setSeenByUsers] = useAtom(TimelineAtoms.seenByUsers);
  const [reactionsPayload, setReactionsPayload] = useAtom(
    TimelineAtoms.reactionsPayload,
  );
  const [shieldPayload, setShieldPayload] = useAtom(
    TimelineAtoms.shieldPayload,
  );
  const { isPinViolatingUsersLoading, violatingUsers, pinViolatingUsers } =
    useRoomIdentityViolations(room);
  const {
    selectedMember,
    isBottomSheetOpen,
    openMemberDetails,
    closeMemberDetails,
  } = useMemberDetails();

  const sortedEvents = useMemo(() => {
    const sorted = [...events].sort(
      (a, b) => Number(a.timestamp) - Number(b.timestamp),
    );

    return filterSameStateKey(sorted);
  }, [events]);

  const eventsWithDividers = useMemo(() => {
    const items = groupInfoEvents(addDateDividers(sortedEvents));

    // Pre-compute isPreviousSameSender so it's not recalculated per-item during render
    let prevSender: string | null = null;
    for (const item of items) {
      if (item.type !== "event") {
        prevSender = null;
        continue;
      }
      const isMsgLike =
        item.data.content.tag === TimelineItemContent_Tags.MsgLike;
      if (!isMsgLike) {
        prevSender = null;
        continue;
      }
      item.isPreviousSameSender =
        isDirect || (prevSender !== null && prevSender === item.data.sender);
      prevSender = item.data.sender;
    }

    return items;
  }, [sortedEvents, isDirect]);

  // Reverse for inverted FlashList: [newest, ..., oldest]
  const reversedEvents = useMemo(
    () => [...eventsWithDividers].reverse(),
    [eventsWithDividers],
  );

  const handleScrollToEvent = useCallback(
    (eventId: string) => {
      const index = reversedEvents.findIndex(
        (item) => item.type === "event" && getEventId(item.data) === eventId,
      );
      if (index === -1) return;

      flashListRef.current?.scrollToIndex({
        index,
        animated: true,
        viewPosition: 0.5,
      });
    },
    [reversedEvents],
  );

  useEffect(() => {
    if (!scrollToEventId) return;
    handleScrollToEvent(scrollToEventId);
    setScrollToEventId(null);
  }, [scrollToEventId, handleScrollToEvent, setScrollToEventId]);

  const handleScrollDown = useCallback(() => {
    // In inverted list, offset 0 is the visual bottom (newest messages)
    suppressScrollDownRef.current = true;
    flashListRef.current?.scrollToOffset({ offset: 0, animated: true });
    setShowNewMessageArrived(false);
    setShowScrollDown(false);
  }, []);

  const handleOnScroll = useCallback(
    ({ nativeEvent }: NativeSyntheticEvent<NativeScrollEvent>) => {
      const { layoutMeasurement, contentOffset, contentSize } = nativeEvent;
      visibleHeightRef.current = layoutMeasurement.height;

      // Inverted list: large contentOffset.y = near oldest messages (visual top)
      // Paginate when within 2x visible height of the oldest content
      const distanceFromTop =
        contentSize.height - contentOffset.y - layoutMeasurement.height;
      const nearTop = distanceFromTop < layoutMeasurement.height * 2;
      if (nearTop && !isPaginatingRef.current && !reachedStartRef.current) {
        loadMoreMessages();
      }

      // Inverted list: contentOffset.y near 0 = at visual bottom (newest messages)
      const paddingToBottom = 100;
      const atBottom = contentOffset.y <= paddingToBottom;
      isAtBottomRef.current = atBottom;

      if (!suppressScrollDownRef.current) setShowScrollDown(!atBottom);

      if (!atBottom) return;
      suppressScrollDownRef.current = false;
      setShowNewMessageArrived(false);
      markAsRead();
    },
    [loadMoreMessages, markAsRead],
  );

  const handleContentSizeChange = useCallback(
    (_w: number, contentHeight: number) => {
      // Auto-paginate if content doesn't fill the viewport (initial fill)
      if (
        contentHeight > 0 &&
        visibleHeightRef.current > 0 &&
        contentHeight < visibleHeightRef.current &&
        !isPaginatingRef.current &&
        !reachedStartRef.current
      ) {
        loadMoreMessages();
      }
    },
    [loadMoreMessages],
  );

  // Unified new-message handler: scroll to bottom or show "new messages" button
  useEffect(() => {
    const lastEvent = sortedEvents[sortedEvents.length - 1];
    const lastEventKey = lastEvent
      ? (getItemUniqueKey(lastEvent) ?? undefined)
      : undefined;
    const isNewEvent = lastEventKey !== lastEventKeyRef.current;
    lastEventKeyRef.current = lastEventKey;

    if (!isNewEvent) return;

    if (lastEvent?.isOwn || isAtBottomRef.current) {
      // Scroll to bottom for own messages or when already at bottom
      flashListRef.current?.scrollToOffset({ offset: 0, animated: true });
      setShowNewMessageArrived(false);
    } else setShowNewMessageArrived(true);
  }, [sortedEvents]);

  const renderItem = useCallback(
    ({ item }: { item: TimelineListItem }) => {
      if (item.type === "divider") {
        return <DateDivider date={item.date} />;
      }

      if (item.type === "group") {
        return <GroupedInfoMessages events={item.events} roomId={roomId} />;
      }

      return (
        <SingleMessageType
          roomId={roomId}
          event={item.data}
          isPreviousSameSender={item.isPreviousSameSender}
          onMemberPress={openMemberDetails}
        />
      );
    },
    [roomId, openMemberDetails],
  );

  const keyExtractor = useCallback((item: TimelineListItem) => {
    if (item.type === "divider") return item.id;
    if (item.type === "group") return item.id;

    return getItemUniqueKey(item.data) ?? "";
  }, []);

  useEffect(() => {
    return () => {
      setReactionsPayload(null);
      setSeenByUsers(null);
      setScrollToEventId(null);
      setShieldPayload(null);
    };
  }, []);

  return (
    <>
      <KeyboardAvoidingView style={styles.flex} behavior="padding">
        {!!violatingUsers.length && (
          <RoomIdentityBanner
            users={violatingUsers}
            isLoading={isPinViolatingUsersLoading}
            onDismiss={pinViolatingUsers}
          />
        )}
        <FlashList
          ref={flashListRef}
          data={reversedEvents}
          inverted
          keyExtractor={keyExtractor}
          contentContainerStyle={styles.listContent}
          onContentSizeChange={handleContentSizeChange}
          onScroll={handleOnScroll}
          renderItem={renderItem}
        />

        <RoomInput roomId={roomId} />
      </KeyboardAvoidingView>

      <MessageContentBottomSheet roomId={roomId} />

      <FailedEchoBottomSheet />

      <MemberDetailsBottomSheet
        isBottomSheetOpen={isBottomSheetOpen}
        selectedMember={selectedMember}
        roomId={roomId}
        onClose={closeMemberDetails}
      />

      <NewMessagesButton
        visible={showNewMessageArrived}
        onPress={handleScrollDown}
      />

      <ScrollToBottomButton
        visible={showScrollDown && !showNewMessageArrived}
        onPress={handleScrollDown}
      />

      <SeenByBottomSheet
        isOpen={!!seenByUsers}
        users={seenByUsers ?? []}
        onClose={() => setSeenByUsers(null)}
      />

      <ReactionsBottomSheet
        isOpen={!!reactionsPayload}
        reactions={reactionsPayload ?? []}
        onClose={() => setReactionsPayload(null)}
      />

      <ShieldModal
        visible={!!shieldPayload}
        onClose={() => setShieldPayload(null)}
        isRed={shieldPayload?.isRed ?? false}
        message={shieldPayload?.message ?? ""}
      />
    </>
  );
};

const styles = StyleSheet.create({
  flex: {
    flex: 1,
  },
  listContent: {
    paddingHorizontal: 20,
    paddingTop: 20,
    paddingBottom: 12,
  },
});

