                <RoomListProvider />
                <IgnoredUsersProvider />
                <SyncLifecycleProvider />
                <PushNotificationsProvider />
                <NetworkStatusBanner />
                <RootNavigator />
                <ImageViewerModal />
                <VideoViewerModal />
                <Toast
                  config={ToastConfig}
                  position="top"
                  topOffset={140}
                  visibilityTime={2000}
                />
              </NavigationContainer>
            </AudioPlaybackProvider>
          </BottomSheetModalProvider>
        </GestureHandlerRootView>
      </SkeletorProvider>
    </SafeAreaProvider>
  );
};

