                </Button.Wrapper>
              )}
            </Block>
            <Block flex={1} align="center" gap={2} zIndex={2}>
              {senderName && (
                <Text
                  color={Colors.white}
                  font="InstrumentSans-Semibold"
                  numberOfLines={1}
                >
                  {senderName}
                </Text>
              )}
              {formattedDate && (
                <Text
                  size={TextSize.tiny}
                  color={Colors.white80}
                  numberOfLines={1}
                >
                  {formattedDate}
                </Text>
              )}
            </Block>
            <Block width={60} align="flex-end" zIndex={2}>
              <Button.Wrapper onPress={onClose}>
                <Text font="InstrumentSans-Semibold" color={Colors.white}>
                  Close
                </Text>
              </Button.Wrapper>
            </Block>
          </Block>

          <Block width={SCREEN_WIDTH} height={SCREEN_HEIGHT}>
            {isLoading && !hasError && (
              <Block
                absolute
                width={SCREEN_WIDTH}
                height={SCREEN_HEIGHT}
                align="center"
                justify="center"
                zIndex={5}
                background={Colors.white10}
              >
                <Loading isFullScreen={false} />
              </Block>
            )}

            {hasError ? (
              <Block
                width={SCREEN_WIDTH}
                height={SCREEN_HEIGHT}
                align="center"
                justify="center"
              >
                <Text color={Colors.white}>Failed to load image</Text>
                <TouchableOpacity
                  onPress={handleRetry}
                  style={styles.retryButton}
                >
                  <Text size={TextSize.small} color={Colors.white}>
                    Tap to retry
                  </Text>
                </TouchableOpacity>
              </Block>
            ) : localUri ? (
              <ImageZoom
                key={localUri}
                uri={localUri}
                minScale={1}
                maxScale={5}
                maxPanPointers={2}
                isPanEnabled
                isPinchEnabled
                isDoubleTapEnabled
                isSingleTapEnabled
                style={styles.image}
                onLoad={handleImageLoad}
                onError={handleImageError}
                onSingleTap={handleSingleTap}
              />
            ) : null}
          </Block>
        </Block>
        <ImageInfoBottomSheet />
      </BottomSheetModalProvider>
    </Modal>
  );
};

const styles = StyleSheet.create({
  image: {
    width: SCREEN_WIDTH,
    height: SCREEN_HEIGHT,
  },
  retryButton: {
    marginTop: 12,
    paddingVertical: 8,
    paddingHorizontal: 16,
  },
  infoIcon: {
    width: 24,
    height: 24,
  },
});

