import { getDefaultStore } from "jotai";
import { NetworkAtoms } from "modules/network/jotai";
import { Toast } from "react-native-toast-message/lib/src/Toast";

export function offlineToastHelper(
  errorMessageOne: string,
  errorMessageTwo?: string,
) {
  const isOffline = getDefaultStore().get(NetworkAtoms.isOffline);

  Toast.show({
    type: "error",
    text1: isOffline
      ? "Request failed. No internet connection."
      : errorMessageOne,
    text2: isOffline ? undefined : errorMessageTwo,
  });
}

