input.new_string:
// When the user lands on a terminal sentinel, show its loading spinner for
// a beat, toast the "no newer/older media" message (once per session), then
// snap back to the adjacent event so they're not stuck on a blank page.
// Older-edge while still paginating (loading=true) is skipped — real items
// will arrive and replace the sentinel's index naturally.
useEffect(() => {
  if (!currentPage) return;
  if (!hasScrolledInitiallyRef.current) return;

  const isTerminalNewer = currentPage.kind === "newer-end";
  const isTerminalOlder =
    currentPage.kind === "older-edge" && !currentPage.loading;
  if (!isTerminalNewer && !isTerminalOlder) return;

  const timer = setTimeout(() => {
    const page = pagesRef.current[currentIndex];
    if (!page) return;
    if (page.kind !== "newer-end" && page.kind !== "older-edge") return;
    if (page.kind === "older-edge" && page.loading) return;

    const edgeKey = isTerminalNewer ? "newer" : "older";
    if (!toastedEdgesRef.current.has(edgeKey)) {
      toastedEdgesRef.current.add(edgeKey);
      Toast.show({
        type: "info",
        text1: isTerminalNewer ? "No newer media" : "No older media",
      });
    }

    const snapIndex = isTerminalNewer ? 1 : currentIndex - 1;
    if (snapIndex >= 0 && snapIndex < pagesRef.current.length) {
      listRef.current?.scrollToIndex({ index: snapIndex, animated: true });
    }
  }, 500);

  return () => clearTimeout(timer);
}, [currentPage, currentIndex]);

